"use client";

import React, { useEffect } from "react";

export default function LandingPage() {
  useEffect(() => {
    let metaScheme = document.querySelector<HTMLMetaElement>('meta[name="color-scheme"]');
    if (!metaScheme) {
      metaScheme = document.createElement("meta");
      metaScheme.name = "color-scheme";
      metaScheme.content = "light dark";
      document.head.appendChild(metaScheme);
    }
    try {
      const saved = localStorage.getItem("color-scheme");
      if (saved === "light" || saved === "dark") {
        metaScheme.content = saved;
      }
    } catch {}

    const tabs = Array.from(document.querySelectorAll<HTMLButtonElement>(".showcase-tab"));
    const urlEl = document.getElementById("showcase-url");
    const captionEl = document.getElementById("showcase-caption-text");

    function activateTab(nextTab: HTMLButtonElement, moveFocus = false) {
      tabs.forEach((tab) => {
        const selected = tab === nextTab;
        tab.setAttribute("aria-selected", selected ? "true" : "false");
        tab.tabIndex = selected ? 0 : -1;
        const panelId = tab.getAttribute("aria-controls");
        const panel = panelId ? document.getElementById(panelId) : null;
        if (panel) panel.hidden = !selected;
      });
      const urlText = nextTab.getAttribute("data-url");
      const captionText = nextTab.getAttribute("data-caption");
      if (urlEl && urlText) {
        urlEl.innerHTML = "<span class=\"lock\" aria-hidden=\"true\">●</span><span>" + urlText + "</span>";
      }
      if (captionEl && captionText) {
        captionEl.innerHTML = "<strong>" + nextTab.textContent + "：</strong>" + captionText;
      }
      if (moveFocus) nextTab.focus();
    }

    tabs.forEach((tab, idx) => {
      tab.tabIndex = idx === 0 ? 0 : -1;
      tab.addEventListener("click", () => activateTab(tab, false));
      tab.addEventListener("keydown", (e: KeyboardEvent) => {
        if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
          e.preventDefault();
          const dir = e.key === "ArrowRight" ? 1 : -1;
          const nextIdx = (idx + dir + tabs.length) % tabs.length;
          activateTab(tabs[nextIdx], true);
        }
      });
    });

    const themeBtn = document.getElementById("theme-toggle");
    if (metaScheme && themeBtn) {
      themeBtn.addEventListener("click", () => {
        let stored: string | null = null;
        try { stored = localStorage.getItem("color-scheme"); } catch {}
        const sysDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
        const currentScheme = (stored === "dark" || stored === "light") ? stored : (sysDark ? "dark" : "light");
        const targetScheme = currentScheme === "dark" ? "light" : "dark";
        const systemScheme = sysDark ? "dark" : "light";

        if (targetScheme === systemScheme) {
          try { localStorage.removeItem("color-scheme"); } catch {}
          metaScheme!.content = "light dark";
        } else {
          try { localStorage.setItem("color-scheme", targetScheme); } catch {}
          metaScheme!.content = targetScheme;
        }
      });
      window.addEventListener("storage", (e: StorageEvent) => {
        if (e.key === "color-scheme") {
          metaScheme!.content = e.newValue ?? "light dark";
        }
      });
    }

    const copyBtn = document.getElementById("copy-cmd-btn");
    if (copyBtn) {
      copyBtn.addEventListener("click", async () => {
        const raw = "git clone https://github.com/pharma-oss/pharma-oss.git\ncd pharma-oss\nnpm install\nnpm run dev";
        try {
          await navigator.clipboard.writeText(raw);
          copyBtn.textContent = "コピーしました";
          setTimeout(() => { copyBtn.textContent = "コピー"; }, 2000);
        } catch {
          copyBtn.textContent = "選択してコピー";
        }
      });
    }
  }, []);

  return (
    <div className="lp-root">
      <style dangerouslySetInnerHTML={{ __html: "\n  :root {\n    --lp-ink-light: #0f3d36;\n    --lp-ink-dark: #09221e;\n    --lp-ink-deep-light: #092924;\n    --lp-ink-deep-dark: #051613;\n\n    --lp-accent-light: #0f766e;\n    --lp-accent-dark: #2dd4bf;\n    --lp-accent-strong-light: #0b5752;\n    --lp-accent-strong-dark: #5eead4;\n\n    --lp-wash-light: #e6f4f1;\n    --lp-wash-dark: #13302b;\n    --lp-wash-subtle-light: #f0f9f7;\n    --lp-wash-subtle-dark: #0f2420;\n\n    --lp-ground-light: #f6faf9;\n    --lp-ground-dark: #0a1412;\n    --lp-surface-light: #ffffff;\n    --lp-surface-dark: #11201d;\n    --lp-surface-elevated-light: #ffffff;\n    --lp-surface-elevated-dark: #162925;\n\n    --lp-heading-light: #0b1f1c;\n    --lp-heading-dark: #f4fbf9;\n    --lp-text-light: #172b27;\n    --lp-text-dark: #e5f2ef;\n    --lp-text-muted-light: #435954;\n    --lp-text-muted-dark: #9cb5af;\n\n    --lp-line-light: #d3e3de;\n    --lp-line-dark: #233b36;\n    --lp-line-strong-light: #b2cec7;\n    --lp-line-strong-dark: #31524b;\n\n    --lp-caution-light: #92540c;\n    --lp-caution-dark: #f5b851;\n    --lp-caution-wash-light: #fef8ec;\n    --lp-caution-wash-dark: #231a0b;\n    --lp-caution-border-light: #e8b96a;\n    --lp-caution-border-dark: #6b4915;\n\n    --lp-ok-light: #0e6f4f;\n    --lp-ok-dark: #4ade80;\n    --lp-ok-wash-light: #ecfdf5;\n    --lp-ok-wash-dark: #0d281d;\n\n    --lp-unimpl-light: #475569;\n    --lp-unimpl-dark: #94a3b8;\n    --lp-unimpl-wash-light: #f1f5f9;\n    --lp-unimpl-wash-dark: #1e293b;\n\n    --lp-btn-primary-text-light: #ffffff;\n    --lp-btn-primary-text-dark: #04241f;\n\n    --lp-ink: var(--lp-ink-light);\n    --lp-ink-deep: var(--lp-ink-deep-light);\n    --lp-accent: var(--lp-accent-light);\n    --lp-accent-strong: var(--lp-accent-strong-light);\n    --lp-wash: var(--lp-wash-light);\n    --lp-wash-subtle: var(--lp-wash-subtle-light);\n    --lp-ground: var(--lp-ground-light);\n    --lp-surface: var(--lp-surface-light);\n    --lp-surface-elevated: var(--lp-surface-elevated-light);\n    --lp-heading: var(--lp-heading-light);\n    --lp-text: var(--lp-text-light);\n    --lp-text-muted: var(--lp-text-muted-light);\n    --lp-line: var(--lp-line-light);\n    --lp-line-strong: var(--lp-line-strong-light);\n    --lp-caution: var(--lp-caution-light);\n    --lp-caution-wash: var(--lp-caution-wash-light);\n    --lp-caution-border: var(--lp-caution-border-light);\n    --lp-ok: var(--lp-ok-light);\n    --lp-ok-wash: var(--lp-ok-wash-light);\n    --lp-unimpl: var(--lp-unimpl-light);\n    --lp-unimpl-wash: var(--lp-unimpl-wash-light);\n    --lp-btn-primary-text: var(--lp-btn-primary-text-light);\n\n    --lp-code-bg: #081e1b;\n    --lp-code-text: #d7f2ec;\n    --lp-code-muted: #82b0a6;\n    --lp-shadow-sm: 0 4px 16px -4px rgba(9, 41, 36, 0.08);\n    --lp-shadow: 0 24px 60px -24px rgba(9, 41, 36, 0.22);\n    --lp-shadow-lg: 0 32px 80px -28px rgba(9, 41, 36, 0.32);\n    --lp-radius-sm: 10px;\n    --lp-radius: 16px;\n    --lp-radius-lg: 22px;\n    --lp-display: \"Hiragino Kaku Gothic ProN\", \"Hiragino Sans\", \"BIZ UDGothic\", \"Yu Gothic UI\", \"Yu Gothic\", \"Noto Sans JP\", sans-serif;\n    --lp-body: \"Hiragino Kaku Gothic ProN\", \"Hiragino Sans\", \"BIZ UDGothic\", \"Yu Gothic UI\", \"Yu Gothic\", \"Noto Sans JP\", sans-serif;\n    --lp-mono: ui-monospace, \"SF Mono\", SFMono-Regular, Menlo, Consolas, monospace;\n\n    color-scheme: light dark;\n    accent-color: var(--lp-accent);\n  }\n\n  @media (prefers-color-scheme: dark) {\n    :root {\n      --lp-ink: var(--lp-ink-dark);\n      --lp-ink-deep: var(--lp-ink-deep-dark);\n      --lp-accent: var(--lp-accent-dark);\n      --lp-accent-strong: var(--lp-accent-strong-dark);\n      --lp-wash: var(--lp-wash-dark);\n      --lp-wash-subtle: var(--lp-wash-subtle-dark);\n      --lp-ground: var(--lp-ground-dark);\n      --lp-surface: var(--lp-surface-dark);\n      --lp-surface-elevated: var(--lp-surface-elevated-dark);\n      --lp-heading: var(--lp-heading-dark);\n      --lp-text: var(--lp-text-dark);\n      --lp-text-muted: var(--lp-text-muted-dark);\n      --lp-line: var(--lp-line-dark);\n      --lp-line-strong: var(--lp-line-strong-dark);\n      --lp-caution: var(--lp-caution-dark);\n      --lp-caution-wash: var(--lp-caution-wash-dark);\n      --lp-caution-border: var(--lp-caution-border-dark);\n      --lp-ok: var(--lp-ok-dark);\n      --lp-ok-wash: var(--lp-ok-wash-dark);\n      --lp-unimpl: var(--lp-unimpl-dark);\n      --lp-unimpl-wash: var(--lp-unimpl-wash-dark);\n      --lp-btn-primary-text: var(--lp-btn-primary-text-dark);\n      --lp-shadow-sm: 0 4px 16px -4px rgba(0, 0, 0, 0.45);\n      --lp-shadow: 0 24px 60px -24px rgba(0, 0, 0, 0.65);\n      --lp-shadow-lg: 0 32px 80px -28px rgba(0, 0, 0, 0.78);\n    }\n  }\n\n  :root:has(> head > meta[name=\"color-scheme\"][content=\"dark\"]) {\n    color-scheme: dark;\n    --lp-ink: var(--lp-ink-dark);\n    --lp-ink-deep: var(--lp-ink-deep-dark);\n    --lp-accent: var(--lp-accent-dark);\n    --lp-accent-strong: var(--lp-accent-strong-dark);\n    --lp-wash: var(--lp-wash-dark);\n    --lp-wash-subtle: var(--lp-wash-subtle-dark);\n    --lp-ground: var(--lp-ground-dark);\n    --lp-surface: var(--lp-surface-dark);\n    --lp-surface-elevated: var(--lp-surface-elevated-dark);\n    --lp-heading: var(--lp-heading-dark);\n    --lp-text: var(--lp-text-dark);\n    --lp-text-muted: var(--lp-text-muted-dark);\n    --lp-line: var(--lp-line-dark);\n    --lp-line-strong: var(--lp-line-strong-dark);\n    --lp-caution: var(--lp-caution-dark);\n    --lp-caution-wash: var(--lp-caution-wash-dark);\n    --lp-caution-border: var(--lp-caution-border-dark);\n    --lp-ok: var(--lp-ok-dark);\n    --lp-ok-wash: var(--lp-ok-wash-dark);\n    --lp-unimpl: var(--lp-unimpl-dark);\n    --lp-unimpl-wash: var(--lp-unimpl-wash-dark);\n    --lp-btn-primary-text: var(--lp-btn-primary-text-dark);\n  }\n\n  :root:has(> head > meta[name=\"color-scheme\"][content=\"light\"]) {\n    color-scheme: light;\n    --lp-ink: var(--lp-ink-light);\n    --lp-ink-deep: var(--lp-ink-deep-light);\n    --lp-accent: var(--lp-accent-light);\n    --lp-accent-strong: var(--lp-accent-strong-light);\n    --lp-wash: var(--lp-wash-light);\n    --lp-wash-subtle: var(--lp-wash-subtle-light);\n    --lp-ground: var(--lp-ground-light);\n    --lp-surface: var(--lp-surface-light);\n    --lp-surface-elevated: var(--lp-surface-elevated-light);\n    --lp-heading: var(--lp-heading-light);\n    --lp-text: var(--lp-text-light);\n    --lp-text-muted: var(--lp-text-muted-light);\n    --lp-line: var(--lp-line-light);\n    --lp-line-strong: var(--lp-line-strong-light);\n    --lp-caution: var(--lp-caution-light);\n    --lp-caution-wash: var(--lp-caution-wash-light);\n    --lp-caution-border: var(--lp-caution-border-light);\n    --lp-ok: var(--lp-ok-light);\n    --lp-ok-wash: var(--lp-ok-wash-light);\n    --lp-unimpl: var(--lp-unimpl-light);\n    --lp-unimpl-wash: var(--lp-unimpl-wash-light);\n    --lp-btn-primary-text: var(--lp-btn-primary-text-light);\n  }\n\n  @supports (color: light-dark(white, black)) {\n    :root {\n      --lp-ink: light-dark(var(--lp-ink-light), var(--lp-ink-dark));\n      --lp-ink-deep: light-dark(var(--lp-ink-deep-light), var(--lp-ink-deep-dark));\n      --lp-accent: light-dark(var(--lp-accent-light), var(--lp-accent-dark));\n      --lp-accent-strong: light-dark(var(--lp-accent-strong-light), var(--lp-accent-strong-dark));\n      --lp-wash: light-dark(var(--lp-wash-light), var(--lp-wash-dark));\n      --lp-wash-subtle: light-dark(var(--lp-wash-subtle-light), var(--lp-wash-subtle-dark));\n      --lp-ground: light-dark(var(--lp-ground-light), var(--lp-ground-dark));\n      --lp-surface: light-dark(var(--lp-surface-light), var(--lp-surface-dark));\n      --lp-surface-elevated: light-dark(var(--lp-surface-elevated-light), var(--lp-surface-elevated-dark));\n      --lp-heading: light-dark(var(--lp-heading-light), var(--lp-heading-dark));\n      --lp-text: light-dark(var(--lp-text-light), var(--lp-text-dark));\n      --lp-text-muted: light-dark(var(--lp-text-muted-light), var(--lp-text-muted-dark));\n      --lp-line: light-dark(var(--lp-line-light), var(--lp-line-dark));\n      --lp-line-strong: light-dark(var(--lp-line-strong-light), var(--lp-line-strong-dark));\n      --lp-caution: light-dark(var(--lp-caution-light), var(--lp-caution-dark));\n      --lp-caution-wash: light-dark(var(--lp-caution-wash-light), var(--lp-caution-wash-dark));\n      --lp-caution-border: light-dark(var(--lp-caution-border-light), var(--lp-caution-border-dark));\n      --lp-ok: light-dark(var(--lp-ok-light), var(--lp-ok-dark));\n      --lp-ok-wash: light-dark(var(--lp-ok-wash-light), var(--lp-ok-wash-dark));\n      --lp-unimpl: light-dark(var(--lp-unimpl-light), var(--lp-unimpl-dark));\n      --lp-unimpl-wash: light-dark(var(--lp-unimpl-wash-light), var(--lp-unimpl-wash-dark));\n      --lp-btn-primary-text: light-dark(var(--lp-btn-primary-text-light), var(--lp-btn-primary-text-dark));\n    }\n  }\n\n  * { box-sizing: border-box; }\n  html { scroll-behavior: smooth; scroll-padding-top: 84px; }\n  body, .lp-root {\n    margin: 0;\n    background: var(--lp-ground);\n    color: var(--lp-text);\n    font-family: var(--lp-body);\n    font-size: 16px;\n    line-height: 1.8;\n    -webkit-font-smoothing: antialiased;\n    overflow-x: clip;\n  }\n  img { max-width: 100%; height: auto; display: block; }\n  a { color: var(--lp-accent-strong); text-underline-offset: 3px; }\n  a:focus-visible, button:focus-visible, summary:focus-visible {\n    outline: 3px solid var(--lp-accent);\n    outline-offset: 3px;\n    border-radius: 6px;\n  }\n\n  /* High-legibility headings that never blend into light or dark backgrounds */\n  h1, h2, h3, h4,\n  .lp-root h1, .lp-root h2, .lp-root h3, .lp-root h4 {\n    color: var(--lp-heading);\n    font-family: var(--lp-display);\n    text-wrap: balance;\n    letter-spacing: -0.015em;\n  }\n  p, li, dd {\n    text-wrap: pretty;\n  }\n\n  .deferred-section {\n    content-visibility: auto;\n    contain-intrinsic-size: auto none auto 680px;\n  }\n\n  .wrap { max-width: 1180px; margin: 0 auto; padding: 0 24px; }\n\n  /* ---- Sticky Header ---- */\n  .site-header-bar {\n    position: sticky;\n    top: 0;\n    z-index: 50;\n    background: color-mix(in srgb, var(--lp-ground) 88%, transparent);\n    backdrop-filter: blur(14px);\n    -webkit-backdrop-filter: blur(14px);\n    border-bottom: 1px solid var(--lp-line);\n  }\n  .site-header {\n    display: flex; align-items: center; justify-content: space-between; gap: 1rem;\n    padding: 12px 0;\n  }\n  .lp-brand {\n    display: inline-flex; align-items: center; gap: 10px;\n    text-decoration: none; color: var(--lp-heading);\n    flex-shrink: 0;\n  }\n  .lp-brand-mark {\n    width: 38px; height: 38px; border-radius: 10px;\n    flex-shrink: 0;\n    box-shadow: 0 6px 16px -4px rgba(15, 118, 110, 0.4);\n  }\n  .lp-brand-name { font-weight: 800; font-size: 1.1rem; letter-spacing: 0.01em; line-height: 1.2; color: var(--lp-heading); white-space: nowrap; }\n  .lp-brand-name small {\n    display: block; font-weight: 600; font-size: 0.68rem;\n    color: var(--lp-text-muted); letter-spacing: 0.03em; margin-top: 2px;\n  }\n  .header-nav {\n    display: flex; align-items: center; gap: 1.15rem;\n  }\n  .header-nav a {\n    text-decoration: none; color: var(--lp-text-muted); font-size: 0.88rem; font-weight: 600;\n    transition: color 0.15s ease;\n    white-space: nowrap;\n  }\n  .header-nav a:hover { color: var(--lp-heading); }\n  .header-links { display: flex; align-items: center; gap: 0.5rem; flex-shrink: 0; }\n\n  .btn {\n    display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem;\n    padding: 0.68rem 1.25rem; border-radius: var(--lp-radius-sm);\n    text-decoration: none; font-weight: 700; font-size: 0.94rem;\n    border: 1.5px solid transparent;\n    cursor: pointer;\n    transition: transform 0.15s ease, background-color 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;\n    line-height: 1.3;\n    white-space: nowrap;\n  }\n  .btn:active { transform: translateY(1px); }\n  .btn-primary {\n    background: var(--lp-accent);\n    color: var(--lp-btn-primary-text);\n    box-shadow: 0 8px 20px -6px rgba(15, 118, 110, 0.45);\n  }\n  .btn-primary:hover { background: var(--lp-accent-strong); }\n  .btn-ghost {\n    border-color: var(--lp-line-strong);\n    color: var(--lp-heading);\n    background: var(--lp-surface);\n  }\n  .btn-ghost:hover { border-color: var(--lp-accent); background: var(--lp-wash-subtle); }\n  .btn-sm { padding: 0.48rem 0.95rem; font-size: 0.85rem; }\n\n  .theme-toggle {\n    display: inline-flex; align-items: center; justify-content: center;\n    width: 38px; height: 38px; border-radius: var(--lp-radius-sm);\n    border: 1.5px solid var(--lp-line);\n    background: var(--lp-surface);\n    color: var(--lp-heading);\n    cursor: pointer;\n    padding: 0;\n  }\n  .theme-toggle:hover { border-color: var(--lp-accent); background: var(--lp-wash-subtle); }\n  .theme-toggle svg { width: 18px; height: 18px; }\n\n  /* ---- Hero ---- */\n  .hero {\n    position: relative;\n    padding: 56px 0 36px;\n  }\n  .hero::before {\n    content: \"\";\n    position: absolute;\n    inset: 0 0 auto;\n    height: 540px;\n    background:\n      radial-gradient(ellipse 70% 55% at 50% 0%, color-mix(in srgb, var(--lp-accent) 12%, transparent), transparent 75%);\n    pointer-events: none;\n    z-index: -1;\n  }\n  .hero-top {\n    max-width: 54em;\n  }\n  .eyebrow-row {\n    display: flex; flex-wrap: wrap; align-items: center; gap: 0.55rem;\n    margin-bottom: 0.95rem;\n  }\n  .eyebrow-pill {\n    display: inline-flex; align-items: center; gap: 0.4rem;\n    font-size: 0.78rem; font-weight: 700; letter-spacing: 0.04em;\n    padding: 0.32rem 0.82rem;\n    border-radius: 999px;\n    background: var(--lp-wash);\n    color: var(--lp-accent-strong);\n    border: 1px solid var(--lp-line-strong);\n  }\n  .eyebrow-pill .dot {\n    width: 7px; height: 7px; border-radius: 50%; background: var(--lp-accent);\n  }\n  .eyebrow {\n    font-size: 0.78rem; font-weight: 800; letter-spacing: 0.12em;\n    color: var(--lp-accent-strong); text-transform: uppercase;\n    margin: 0;\n  }\n  h1, .lp-root h1 {\n    font-size: clamp(1.9rem, 3.6vw, 2.75rem);\n    line-height: 1.34;\n    margin: 0.25rem 0 1.15rem;\n    font-weight: 800;\n    color: var(--lp-heading);\n    text-wrap: initial;\n  }\n  h1 .accent-text {\n    color: var(--lp-accent-strong);\n    text-decoration: underline;\n    text-decoration-color: color-mix(in srgb, var(--lp-accent) 45%, transparent);\n    text-decoration-thickness: 0.14em;\n    text-underline-offset: 0.14em;\n  }\n  .hero-lede {\n    max-width: 44em;\n    font-size: 1.06rem;\n    color: var(--lp-text);\n    margin: 0 0 1.65rem;\n    line-height: 1.85;\n  }\n  .hero-lede strong { color: var(--lp-heading); font-weight: 700; }\n  .hero-ctas { display: flex; flex-wrap: wrap; align-items: center; gap: 0.75rem; margin-bottom: 1rem; }\n  .hero-note {\n    font-size: 0.82rem; color: var(--lp-text-muted); margin: 0;\n  }\n\n  /* ---- Key Benefits Strip ---- */\n  .metrics-strip {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 0.9rem;\n    margin: 28px 0 32px;\n  }\n  .metric-card {\n    background: var(--lp-surface);\n    border: 1px solid var(--lp-line);\n    border-radius: var(--lp-radius);\n    padding: 1.1rem 1.25rem;\n    box-shadow: var(--lp-shadow-sm);\n  }\n  .metric-val {\n    font-family: var(--lp-display);\n    font-size: 1.45rem;\n    font-weight: 800;\n    color: var(--lp-accent-strong);\n    line-height: 1.25;\n  }\n  .metric-val small {\n    font-size: 0.82rem;\n    font-weight: 700;\n    margin-left: 3px;\n    color: var(--lp-text-muted);\n  }\n  .metric-label {\n    font-size: 0.92rem;\n    font-weight: 700;\n    color: var(--lp-heading);\n    margin-top: 0.25rem;\n  }\n  .metric-sub {\n    font-size: 0.8rem;\n    color: var(--lp-text-muted);\n    margin-top: 0.2rem;\n    line-height: 1.55;\n  }\n\n  /* ---- Interactive Product Showcase ---- */\n  .showcase {\n    margin: 16px 0 0;\n    background: var(--lp-surface-elevated);\n    border: 1px solid var(--lp-line-strong);\n    border-radius: var(--lp-radius-lg);\n    box-shadow: var(--lp-shadow-lg);\n    overflow: hidden;\n  }\n  .showcase-bar {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    justify-content: space-between;\n    gap: 0.75rem;\n    padding: 0.75rem 1.1rem;\n    background: var(--lp-wash-subtle);\n    border-bottom: 1px solid var(--lp-line);\n  }\n  .window-dots {\n    display: inline-flex; align-items: center; gap: 7px;\n  }\n  .window-dots span {\n    width: 11px; height: 11px; border-radius: 50%;\n    background: var(--lp-line-strong);\n  }\n  .window-dots span:nth-child(1) { background: #f87171; }\n  .window-dots span:nth-child(2) { background: #fbbf24; }\n  .window-dots span:nth-child(3) { background: #34d399; }\n  .window-url {\n    font-family: var(--lp-mono);\n    font-size: 0.78rem;\n    color: var(--lp-text-muted);\n    background: var(--lp-surface);\n    border: 1px solid var(--lp-line);\n    border-radius: 999px;\n    padding: 0.22rem 0.85rem;\n    display: inline-flex;\n    align-items: center;\n    gap: 0.4rem;\n  }\n  .window-url .lock { color: var(--lp-ok); font-weight: 700; }\n  .showcase-tabs {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 0.4rem;\n    padding: 0.7rem 1.1rem;\n    background: var(--lp-surface);\n    border-bottom: 1px solid var(--lp-line);\n  }\n  .showcase-tab {\n    appearance: none;\n    border: 1px solid var(--lp-line);\n    background: var(--lp-ground);\n    color: var(--lp-text);\n    font-family: var(--lp-body);\n    font-size: 0.82rem;\n    font-weight: 700;\n    padding: 0.44rem 0.88rem;\n    border-radius: 999px;\n    cursor: pointer;\n    transition: all 0.15s ease;\n    min-height: 36px;\n  }\n  .showcase-tab:hover {\n    border-color: var(--lp-accent);\n    color: var(--lp-heading);\n  }\n  .showcase-tab[aria-selected=\"true\"] {\n    background: var(--lp-accent);\n    color: var(--lp-btn-primary-text);\n    border-color: var(--lp-accent);\n    box-shadow: 0 4px 12px -3px rgba(15, 118, 110, 0.45);\n  }\n  .showcase-stage {\n    position: relative;\n    background: var(--lp-ink-deep);\n  }\n  .showcase-panel {\n    margin: 0;\n  }\n  .showcase-panel[hidden] {\n    display: none;\n  }\n  .showcase-caption {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    justify-content: space-between;\n    gap: 0.75rem;\n    padding: 0.85rem 1.25rem;\n    background: var(--lp-surface);\n    border-top: 1px solid var(--lp-line);\n    font-size: 0.86rem;\n    color: var(--lp-text-muted);\n  }\n  .showcase-caption strong { color: var(--lp-heading); }\n\n  /* ---- 4 Reasons to Choose ---- */\n  section { padding: 76px 0 12px; }\n  .section-head { max-width: 48em; margin-bottom: 2.4rem; }\n  h2, .lp-root h2 {\n    font-size: clamp(1.55rem, 3.2vw, 2.15rem);\n    font-weight: 800;\n    line-height: 1.36;\n    margin: 0.35rem 0 0.75rem;\n    color: var(--lp-heading);\n  }\n  .section-head p { margin: 0; color: var(--lp-text-muted); font-size: 0.98rem; line-height: 1.8; }\n\n  .pillars {\n    display: grid;\n    grid-template-columns: repeat(2, 1fr);\n    gap: 1.2rem;\n  }\n  .pillar {\n    background: var(--lp-surface);\n    border: 1px solid var(--lp-line);\n    border-radius: var(--lp-radius);\n    padding: 1.55rem 1.65rem;\n    box-shadow: var(--lp-shadow-sm);\n    display: flex;\n    flex-direction: column;\n    gap: 0.55rem;\n    position: relative;\n    overflow: hidden;\n  }\n  .pillar::before {\n    content: \"\";\n    position: absolute;\n    inset: 0 auto 0 0;\n    width: 4px;\n    background: var(--lp-accent);\n  }\n  .pillar-head {\n    display: flex; align-items: center; justify-content: space-between; gap: 0.75rem;\n  }\n  .pillar-num {\n    font-size: 0.76rem;\n    font-weight: 800;\n    letter-spacing: 0.06em;\n    color: var(--lp-accent-strong);\n    background: var(--lp-wash);\n    padding: 0.24rem 0.7rem;\n    border-radius: 999px;\n  }\n  .pillar h3 { margin: 0; font-size: 1.15rem; font-weight: 800; color: var(--lp-heading); line-height: 1.4; }\n  .pillar p { margin: 0; font-size: 0.92rem; color: var(--lp-text-muted); line-height: 1.78; }\n  .pillar-tags { display: flex; flex-wrap: wrap; gap: 0.4rem; margin-top: 0.35rem; }\n  .pillar-tag {\n    font-size: 0.75rem; font-weight: 600;\n    padding: 0.2rem 0.6rem;\n    border-radius: 6px;\n    background: var(--lp-wash-subtle);\n    color: var(--lp-text);\n    border: 1px solid var(--lp-line);\n  }\n\n  /* ---- End-to-End Daily Workflow ---- */\n  .flow-row {\n    display: grid;\n    grid-template-columns: minmax(0, 5fr) minmax(0, 6.2fr);\n    gap: 2.5rem;\n    align-items: center;\n    padding: 2.6rem 0;\n    border-top: 1px solid var(--lp-line);\n  }\n  .flow-row.reverse { grid-template-columns: minmax(0, 6.2fr) minmax(0, 5fr); }\n  .flow-row.reverse .flow-copy { order: 2; }\n  .flow-row.reverse .flow-media { order: 1; }\n  .flow-step {\n    display: inline-flex; align-items: center; gap: 0.5rem;\n    font-size: 0.8rem; letter-spacing: 0.06em;\n    color: var(--lp-accent-strong); font-weight: 800;\n    margin: 0 0 0.35rem;\n  }\n  .flow-row h3 {\n    font-size: 1.42rem;\n    font-weight: 800;\n    margin: 0 0 0.65rem;\n    line-height: 1.4;\n    color: var(--lp-heading);\n  }\n  .flow-row p { margin: 0 0 0.85rem; font-size: 0.94rem; color: var(--lp-text-muted); }\n  .flow-list {\n    margin: 0 0 0.95rem;\n    padding-left: 1.2em;\n    font-size: 0.9rem;\n    color: var(--lp-text-muted);\n  }\n  .flow-list li { margin: 0.4rem 0; line-height: 1.72; }\n  .flow-list li strong { color: var(--lp-heading); font-weight: 700; }\n  .flow-media {\n    border: 1px solid var(--lp-line-strong);\n    border-radius: var(--lp-radius);\n    overflow: hidden;\n    box-shadow: var(--lp-shadow);\n    background: var(--lp-surface);\n    margin: 0;\n  }\n  .flow-media figcaption {\n    padding: 0.6rem 1rem;\n    font-size: 0.8rem;\n    color: var(--lp-text-muted);\n    background: var(--lp-surface);\n    border-top: 1px solid var(--lp-line);\n  }\n  .chip-row { display: flex; flex-wrap: wrap; gap: 0.42rem; margin-top: 0.75rem; }\n  .chip {\n    font-size: 0.76rem; font-weight: 700; padding: 0.26rem 0.68rem;\n    background: var(--lp-wash); color: var(--lp-accent-strong);\n    border-radius: 999px; border: 1px solid var(--lp-line-strong);\n  }\n  .chip.chip-muted {\n    background: var(--lp-unimpl-wash);\n    color: var(--lp-unimpl);\n    border-color: var(--lp-line);\n  }\n\n  /* ---- 11 Print Sheets & Operations Grid ---- */\n  .sheets-banner {\n    background: var(--lp-surface);\n    border: 1px solid var(--lp-line);\n    border-radius: var(--lp-radius);\n    padding: 1.5rem 1.7rem;\n    margin-bottom: 1.4rem;\n    box-shadow: var(--lp-shadow-sm);\n  }\n  .sheets-banner h3 {\n    margin: 0 0 0.45rem;\n    font-size: 1.1rem;\n    color: var(--lp-heading);\n  }\n  .sheets-banner p {\n    margin: 0 0 1rem;\n    font-size: 0.9rem;\n    color: var(--lp-text-muted);\n  }\n  .sheets-pills {\n    display: flex; flex-wrap: wrap; gap: 0.5rem;\n  }\n  .sheet-pill {\n    display: inline-flex; align-items: center; gap: 0.38rem;\n    font-size: 0.82rem; font-weight: 700;\n    padding: 0.38rem 0.8rem;\n    border-radius: 8px;\n    background: var(--lp-wash-subtle);\n    border: 1px solid var(--lp-line-strong);\n    color: var(--lp-heading);\n  }\n  .sheet-pill small {\n    font-weight: 600;\n    color: var(--lp-accent-strong);\n    font-size: 0.74rem;\n  }\n\n  .grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }\n  .cell {\n    background: var(--lp-surface);\n    border: 1px solid var(--lp-line);\n    border-radius: var(--lp-radius);\n    padding: 1.25rem 1.3rem;\n    box-shadow: var(--lp-shadow-sm);\n  }\n  .cell-kicker {\n    font-size: 0.74rem;\n    font-weight: 800;\n    color: var(--lp-accent-strong);\n    letter-spacing: 0.04em;\n    margin-bottom: 0.25rem;\n  }\n  .cell h4 { margin: 0 0 0.4rem; font-size: 0.98rem; font-weight: 800; color: var(--lp-heading); }\n  .cell p { margin: 0; font-size: 0.85rem; color: var(--lp-text-muted); line-height: 1.7; }\n\n  /* ---- Store Styles (Single PC vs Multiple PCs) ---- */\n  .arch-layout {\n    display: grid;\n    grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);\n    gap: 1.5rem;\n    align-items: start;\n  }\n  .arch-card {\n    background: var(--lp-surface);\n    border: 1px solid var(--lp-line);\n    border-radius: var(--lp-radius);\n    padding: 1.5rem 1.6rem;\n    box-shadow: var(--lp-shadow-sm);\n  }\n  .arch-card h3 { margin: 0 0 0.85rem; font-size: 1.1rem; color: var(--lp-heading); }\n  .arch-diagram {\n    display: grid;\n    gap: 0.9rem;\n    margin-bottom: 1.1rem;\n  }\n  .arch-mode {\n    background: var(--lp-wash-subtle);\n    border: 1px solid var(--lp-line-strong);\n    border-radius: var(--lp-radius-sm);\n    padding: 0.95rem 1.1rem;\n  }\n  .arch-mode-title {\n    display: flex; align-items: center; justify-content: space-between; gap: 0.5rem;\n    font-weight: 800; font-size: 0.92rem; margin-bottom: 0.45rem; color: var(--lp-heading);\n  }\n  .arch-mode-badge {\n    font-size: 0.74rem; font-weight: 700;\n    padding: 0.16rem 0.6rem; border-radius: 999px;\n    background: var(--lp-surface); border: 1px solid var(--lp-line); color: var(--lp-accent-strong);\n  }\n  .arch-nodes {\n    display: flex; flex-wrap: wrap; align-items: center; gap: 0.45rem;\n    font-size: 0.82rem;\n  }\n  .arch-node {\n    background: var(--lp-surface);\n    border: 1px solid var(--lp-line);\n    border-radius: 8px;\n    padding: 0.35rem 0.65rem;\n    font-weight: 600;\n    color: var(--lp-text);\n  }\n  .arch-arrow { color: var(--lp-accent-strong); font-weight: 800; }\n\n  .spec-table {\n    width: 100%;\n    border-collapse: collapse;\n    font-size: 0.86rem;\n  }\n  .spec-table th, .spec-table td {\n    text-align: left;\n    padding: 0.65rem 0.55rem;\n    border-bottom: 1px solid var(--lp-line);\n    vertical-align: top;\n  }\n  .spec-table th {\n    width: 36%;\n    color: var(--lp-heading);\n    font-weight: 700;\n  }\n  .spec-table td { color: var(--lp-text-muted); }\n  .spec-table tr:last-child th, .spec-table tr:last-child td { border-bottom: none; }\n\n  /* ---- Implementation Status Matrix & Disclaimer ---- */\n  .status-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 1rem;\n    margin-bottom: 1.5rem;\n  }\n  .status-col {\n    background: var(--lp-surface);\n    border: 1px solid var(--lp-line);\n    border-radius: var(--lp-radius);\n    padding: 1.3rem 1.4rem;\n    box-shadow: var(--lp-shadow-sm);\n  }\n  .status-badge {\n    display: inline-flex; align-items: center; gap: 0.35rem;\n    font-size: 0.76rem; font-weight: 800;\n    padding: 0.26rem 0.7rem; border-radius: 999px;\n    margin-bottom: 0.65rem;\n  }\n  .status-badge.ok { background: var(--lp-ok-wash); color: var(--lp-ok); border: 1px solid color-mix(in srgb, var(--lp-ok) 35%, transparent); }\n  .status-badge.warn { background: var(--lp-caution-wash); color: var(--lp-caution); border: 1px solid var(--lp-caution-border); }\n  .status-badge.unimpl { background: var(--lp-unimpl-wash); color: var(--lp-unimpl); border: 1px solid var(--lp-line-strong); }\n  .status-col h3 { margin: 0 0 0.55rem; font-size: 1.02rem; color: var(--lp-heading); }\n  .status-col ul { margin: 0; padding-left: 1.15em; font-size: 0.86rem; color: var(--lp-text-muted); }\n  .status-col li { margin: 0.4rem 0; line-height: 1.68; }\n  .status-col li strong { color: var(--lp-heading); }\n\n  .honesty {\n    border: 1.5px solid var(--lp-caution-border);\n    background: var(--lp-caution-wash);\n    border-radius: var(--lp-radius);\n    padding: 1.6rem 1.85rem;\n  }\n  .honesty h3 {\n    font-size: 1.22rem;\n    margin: 0.25rem 0 0.65rem;\n    color: var(--lp-heading);\n  }\n  .honesty p, .honesty li { font-size: 0.91rem; color: var(--lp-text); }\n  .honesty ul { padding-left: 1.2em; margin: 0.6rem 0 0; }\n  .honesty li { margin: 0.38rem 0; }\n  .honesty .label {\n    display: inline-block;\n    color: var(--lp-caution);\n    font-weight: 800;\n    letter-spacing: 0.06em;\n    font-size: 0.78rem;\n  }\n\n  /* ---- Getting Started & Dark Code Block ---- */\n  .start-grid {\n    display: grid;\n    grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr);\n    gap: 2rem;\n    align-items: start;\n  }\n  .terminal-card {\n    color-scheme: dark;\n    background: var(--lp-code-bg);\n    color: var(--lp-code-text);\n    accent-color: var(--lp-accent);\n    border-radius: var(--lp-radius);\n    border: 1px solid #1e423b;\n    box-shadow: var(--lp-shadow);\n    overflow: hidden;\n  }\n  .terminal-head {\n    display: flex; align-items: center; justify-content: space-between;\n    padding: 0.65rem 1rem;\n    background: #051412;\n    border-bottom: 1px solid #183630;\n    font-family: var(--lp-mono);\n    font-size: 0.76rem;\n    color: var(--lp-code-muted);\n  }\n  .copy-btn {\n    appearance: none;\n    background: #12352e;\n    color: var(--lp-code-text);\n    border: 1px solid #25574d;\n    border-radius: 6px;\n    padding: 0.26rem 0.65rem;\n    font-family: var(--lp-body);\n    font-size: 0.74rem;\n    font-weight: 700;\n    cursor: pointer;\n    min-height: 30px;\n  }\n  .copy-btn:hover { background: #19473e; }\n  pre {\n    color-scheme: dark;\n    background: var(--lp-code-bg);\n    color: var(--lp-code-text);\n    accent-color: var(--lp-accent);\n    font-family: var(--lp-mono);\n    font-size: 0.88rem;\n    line-height: 1.9;\n    padding: 1.25rem 1.4rem;\n    margin: 0;\n    overflow-x: auto;\n  }\n  pre .c { color: var(--lp-code-muted); }\n  pre .cmd { color: #5eead4; font-weight: 600; }\n\n  .start-routes {\n    display: grid;\n    gap: 0.9rem;\n  }\n  .route-card {\n    background: var(--lp-surface);\n    border: 1px solid var(--lp-line);\n    border-radius: var(--lp-radius);\n    padding: 1.2rem 1.4rem;\n    box-shadow: var(--lp-shadow-sm);\n  }\n  .route-card h3 {\n    margin: 0 0 0.5rem;\n    font-size: 1.02rem;\n    display: flex;\n    align-items: center;\n    gap: 0.5rem;\n    color: var(--lp-heading);\n  }\n  .route-badge {\n    font-size: 0.74rem;\n    font-weight: 800;\n    padding: 0.18rem 0.6rem;\n    border-radius: 999px;\n    background: var(--lp-wash);\n    color: var(--lp-accent-strong);\n  }\n  ol.steps { margin: 0; padding-left: 1.25em; font-size: 0.9rem; color: var(--lp-text-muted); }\n  ol.steps li { margin: 0.42rem 0; line-height: 1.72; }\n  ol.steps strong { color: var(--lp-heading); font-weight: 700; }\n\n  /* ---- Native <details> FAQ ---- */\n  .faq-list {\n    margin-top: 2.2rem;\n    display: grid;\n    gap: 0.65rem;\n  }\n  details.faq-item {\n    background: var(--lp-surface);\n    border: 1px solid var(--lp-line);\n    border-radius: var(--lp-radius-sm);\n    padding: 1rem 1.3rem;\n    transition: border-color 0.15s ease;\n  }\n  details.faq-item[open] {\n    border-color: var(--lp-accent);\n  }\n  details.faq-item summary {\n    font-weight: 700;\n    font-size: 0.96rem;\n    color: var(--lp-heading);\n    cursor: pointer;\n    list-style: none;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 1rem;\n  }\n  details.faq-item summary::-webkit-details-marker { display: none; }\n  details.faq-item summary::after {\n    content: \"+\";\n    font-family: var(--lp-mono);\n    font-size: 1.15rem;\n    font-weight: 700;\n    color: var(--lp-accent-strong);\n    flex-shrink: 0;\n  }\n  details.faq-item[open] summary::after { content: \"−\"; }\n  details.faq-item .faq-body {\n    margin-top: 0.75rem;\n    padding-top: 0.75rem;\n    border-top: 1px solid var(--lp-line);\n    font-size: 0.9rem;\n    color: var(--lp-text-muted);\n    line-height: 1.8;\n  }\n\n  /* ---- CTA Band & Footer ---- */\n  .cta-band {\n    margin: 80px 0 0;\n    background: linear-gradient(135deg, var(--lp-ink) 0%, var(--lp-ink-deep) 100%);\n    color: #eaf6f3;\n    padding: 68px 0;\n    border-top: 1px solid var(--lp-line);\n  }\n  .cta-band h2, .lp-root .cta-band h2 { color: #ffffff; margin-top: 0; }\n  .cta-band p { color: #c4e3dc; max-width: 44em; margin-bottom: 1.6rem; }\n  .cta-band .btn-primary { background: #2dd4bf; color: #04241f; box-shadow: none; }\n  .cta-band .btn-primary:hover { background: #5eead4; }\n  .cta-band .btn-ghost { background: rgba(255, 255, 255, 0.08); color: #ffffff; border-color: rgba(255, 255, 255, 0.28); }\n  .cta-band .btn-ghost:hover { border-color: #ffffff; background: rgba(255, 255, 255, 0.15); }\n\n  footer { padding: 32px 0 48px; font-size: 0.84rem; color: var(--lp-text-muted); }\n  .foot-row { display: flex; flex-wrap: wrap; gap: 1rem; justify-content: space-between; align-items: center; }\n  .foot-links { display: flex; flex-wrap: wrap; gap: 1rem; }\n  footer a { color: var(--lp-text-muted); text-decoration: none; }\n  footer a:hover { color: var(--lp-heading); text-decoration: underline; }\n\n  @media (prefers-reduced-motion: reduce) {\n    html { scroll-behavior: auto; }\n    *, *::before, *::after { animation: none !important; transition: none !important; }\n  }\n\n  @media (max-width: 960px) {\n    .header-nav { display: none; }\n    .metrics-strip { grid-template-columns: repeat(2, 1fr); }\n    .pillars, .arch-layout, .status-grid, .start-grid { grid-template-columns: 1fr; }\n    .grid { grid-template-columns: repeat(2, 1fr); }\n    .flow-row, .flow-row.reverse { grid-template-columns: 1fr; gap: 1.3rem; }\n    .flow-row.reverse .flow-copy { order: 1; }\n    .flow-row.reverse .flow-media { order: 2; }\n  }\n  @media (max-width: 580px) {\n    .metrics-strip, .grid { grid-template-columns: 1fr; }\n    .header-links .btn-ghost { display: none; }\n    .showcase-bar .window-url { display: none; }\n    .lp-brand-name small { display: none; }\n  }\n" }} />
      <div dangerouslySetInnerHTML={{ __html: "\n\n<div class=\"site-header-bar\">\n  <div class=\"wrap\">\n    <header class=\"site-header\">\n      <a class=\"lp-brand\" href=\"#top\">\n        <svg class=\"lp-brand-mark\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\" width=\"40\" height=\"40\" aria-hidden=\"true\">\n          <defs>\n            <linearGradient id=\"brandTileGrad\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n              <stop offset=\"0\" stop-color=\"#2AD3BE\" />\n              <stop offset=\"0.55\" stop-color=\"#0F766E\" />\n              <stop offset=\"1\" stop-color=\"#0B5766\" />\n            </linearGradient>\n            <radialGradient id=\"brandTileGloss\" cx=\"0.28\" cy=\"0.18\" r=\"0.78\">\n              <stop offset=\"0\" stop-color=\"#ffffff\" stop-opacity=\"0.32\" />\n              <stop offset=\"1\" stop-color=\"#ffffff\" stop-opacity=\"0\" />\n            </radialGradient>\n            <clipPath id=\"brandCapsuleClip\">\n              <rect x=\"95\" y=\"185\" width=\"322\" height=\"142\" rx=\"71\" />\n            </clipPath>\n          </defs>\n          <rect width=\"512\" height=\"512\" rx=\"112\" fill=\"url(#brandTileGrad)\" />\n          <rect width=\"512\" height=\"512\" rx=\"112\" fill=\"url(#brandTileGloss)\" />\n          <g transform=\"rotate(-45 256 256)\">\n            <g clip-path=\"url(#brandCapsuleClip)\">\n              <rect x=\"95\" y=\"185\" width=\"158\" height=\"142\" fill=\"#ffffff\" />\n              <rect x=\"259\" y=\"185\" width=\"158\" height=\"142\" fill=\"#ffffff\" fill-opacity=\"0.55\" />\n              <g fill=\"#ffffff\" fill-opacity=\"0.95\">\n                <circle cx=\"302\" cy=\"232\" r=\"9.5\" />\n                <circle cx=\"352\" cy=\"256\" r=\"9.5\" />\n                <circle cx=\"302\" cy=\"280\" r=\"9.5\" />\n              </g>\n            </g>\n          </g>\n        </svg>\n        <span class=\"lp-brand-name\">pharma-oss<small>調剤薬局向け 電子薬歴・レセプト・在庫管理</small></span>\n      </a>\n      <nav class=\"header-nav\" aria-label=\"ページ内ナビゲーション\">\n        <a href=\"#pillars\">選ばれる理由</a>\n        <a href=\"#workflow\">1日の業務フロー</a>\n        <a href=\"#operations\">帳票・便利機能</a>\n        <a href=\"#architecture\">店舗での使い方</a>\n        <a href=\"#status\">対応範囲・ご注意</a>\n      </nav>\n      <div class=\"header-links\">\n        <button type=\"button\" class=\"theme-toggle\" id=\"theme-toggle\" aria-label=\"表示テーマを切り替え\" title=\"ライト / ダークモード切替\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n            <circle cx=\"12\" cy=\"12\" r=\"4\"></circle>\n            <path d=\"M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M19.07 4.93l-1.41 1.41\"></path>\n          </svg>\n        </button>\n        <a class=\"btn btn-ghost btn-sm\" href=\"/app\">アプリを開く</a>\n        <a class=\"btn btn-primary btn-sm\" href=\"https://github.com/pharma-oss/pharma-oss\">GitHub</a>\n      </div>\n    </header>\n  </div>\n</div>\n\n<div class=\"wrap\">\n  <main id=\"top\">\n    <!-- ==================== HERO ==================== -->\n    <section class=\"hero\" aria-labelledby=\"hero-title\">\n      <div class=\"hero-top\">\n        <div class=\"eyebrow-row\">\n          <span class=\"eyebrow-pill\"><span class=\"dot\" aria-hidden=\"true\"></span>電子薬歴・レセプト・在庫管理をオールインワン</span>\n          <span class=\"eyebrow-pill\">月額費用 0円（オープンソース）</span>\n          <span class=\"eyebrow-pill\">令和8年（2026年）調剤報酬対応</span>\n        </div>\n        <h1 id=\"hero-title\">毎日の調剤・薬歴・レセプト・発注を、<br><span class=\"accent-text\">迷わず、ひと続きの画面で。</span></h1>\n        <p class=\"hero-lede\">\n          処方箋の読み取りから、バーコードでのピッキング照合、前回との違いがひと目でわかるSOAP薬歴、薬袋・薬情・手帳シールの印刷、毎月のレセプト（UKE）出力、不足薬の発注まで。\n          <strong>pharma-oss</strong> は、薬局の1日に必要な業務をシンプルにつなぐ無料のオープンソース・システムです。\n        </p>\n        <div class=\"hero-ctas\">\n          <a class=\"btn btn-primary\" href=\"/app\">今すぐアプリを開く</a>\n          <a class=\"btn btn-ghost\" href=\"https://github.com/pharma-oss/pharma-oss/blob/main/docs/field_operation_manual.md\">現場運用マニュアルを見る</a>\n          <a class=\"btn btn-ghost\" href=\"https://github.com/pharma-oss/pharma-oss\">GitHub</a>\n        </div>\n        <p class=\"hero-note\">\n          ※ログイン設定なしで、架空のデモ患者データを使って今すぐ画面を触れます。実運用時は <a href=\"#status\">対応範囲と注意事項</a> をご確認ください。\n        </p>\n      </div>\n\n      <!-- Key Benefits Strip -->\n      <div class=\"metrics-strip\" role=\"list\" aria-label=\"主な特徴\">\n        <div class=\"metric-card\" role=\"listitem\">\n          <div class=\"metric-val\">受付〜発注まで</div>\n          <div class=\"metric-label\">画面を行き来せず完結</div>\n          <div class=\"metric-sub\">受付・ピッキング・薬歴・会計・UKE出力・発注が1つの流れでつながります</div>\n        </div>\n        <div class=\"metric-card\" role=\"listitem\">\n          <div class=\"metric-val\">11<small>種類の帳票</small></div>\n          <div class=\"metric-label\">薬袋・薬情・手帳シールもすぐ印刷</div>\n          <div class=\"metric-sub\">領収証・明細書・水剤/軟膏ラベル・トレーシングレポートまで標準対応</div>\n        </div>\n        <div class=\"metric-card\" role=\"listitem\">\n          <div class=\"metric-val\">うっかり防止</div>\n          <div class=\"metric-label\">照合漏れ・算定漏れを画面でストップ</div>\n          <div class=\"metric-sub\">GS1バーコード照合や相互作用チェック、請求前の必須項目点検を自動サポート</div>\n        </div>\n        <div class=\"metric-card\" role=\"listitem\">\n          <div class=\"metric-val\">月額 0<small>円</small></div>\n          <div class=\"metric-label\">契約縛り・更新料なし</div>\n          <div class=\"metric-sub\">お店のパソコンでそのまま動き、インターネットが不安定な日も業務が止まりません</div>\n        </div>\n      </div>\n\n      <!-- Interactive Screen Showcase -->\n      <div class=\"showcase\" aria-label=\"製品画面プレビュー\">\n        <div class=\"showcase-bar\">\n          <div class=\"window-dots\" aria-hidden=\"true\"><span></span><span></span><span></span></div>\n          <div class=\"window-url\" id=\"showcase-url\">\n            <span class=\"lock\" aria-hidden=\"true\">●</span>\n            <span>調剤・監査ダッシュボード — 本日の受付と進行状況</span>\n          </div>\n          <span style=\"font-size:0.78rem;color:var(--lp-text-muted);font-weight:600;\">タブで実際の画面を切り替え</span>\n        </div>\n        <div class=\"showcase-tabs\" role=\"tablist\" aria-label=\"画面切り替え\">\n          <button type=\"button\" class=\"showcase-tab\" role=\"tab\" aria-selected=\"true\" aria-controls=\"panel-dashboard\" id=\"tab-dashboard\" data-url=\"調剤・監査ダッシュボード — 本日の受付と進行状況\" data-caption=\"今日の受付件数、お待ちの患者さん、未完了の作業（ピッキング未照合・請求チェック・在庫不足）がひと目でわかります。\">ダッシュボード</button>\n          <button type=\"button\" class=\"showcase-tab\" role=\"tab\" aria-selected=\"false\" aria-controls=\"panel-ocr\" id=\"tab-ocr\" data-url=\"01 処方箋受付 — カメラ読取・QR・手入力\" data-caption=\"処方箋の画像と読み取り結果を横に並べて見比べながら受付。過去に来局された患者さんは自動で呼び出します。\">01 処方箋受付</button>\n          <button type=\"button\" class=\"showcase-tab\" role=\"tab\" aria-selected=\"false\" aria-controls=\"panel-picking\" id=\"tab-picking\" data-url=\"02 ピッキング照合 — 棚番地ガイド＆バーコード確認\" data-caption=\"棚番地の順番通りに薬を集め、GS1バーコードを読むだけで「薬品・使用期限・ロット」の取り違えを防ぎます。\">02 ピッキング照合</button>\n          <button type=\"button\" class=\"showcase-tab\" role=\"tab\" aria-selected=\"false\" aria-controls=\"panel-emr\" id=\"tab-emr\" data-url=\"03 電子薬歴 (SOAP) — 前回比較＆AI下書き補助\" data-caption=\"前回の薬歴や処方の変更点を見ながら、チェックを入れるだけでSOAP下書きを作成。アレルギーや飲み合わせも自動で警告します。\">03 電子薬歴 (SOAP)</button>\n          <button type=\"button\" class=\"showcase-tab\" role=\"tab\" aria-selected=\"false\" aria-controls=\"panel-print\" id=\"tab-print\" data-url=\"04 会計・帳票印刷・レセプト点検\" data-caption=\"調剤報酬の自動計算、薬袋・薬情・領収証などの一括印刷、毎月のレセプト（UKE）出力前のエラーチェックを行います。\">04 会計・帳票・レセプト</button>\n          <button type=\"button\" class=\"showcase-tab\" role=\"tab\" aria-selected=\"false\" aria-controls=\"panel-inventory\" id=\"tab-inventory\" data-url=\"05 在庫・発注管理 — 不足薬や期限切迫を自動リストアップ\" data-caption=\"調剤中に足りなくなった薬や発注点を下回った薬、期限が近い薬を自動でまとめ、そのまま発注リストを作れます。\">05 在庫・発注管理</button>\n        </div>\n        <div class=\"showcase-stage\">\n          <figure class=\"showcase-panel\" id=\"panel-dashboard\" role=\"tabpanel\" aria-labelledby=\"tab-dashboard\">\n            <img src=\"/images/lp/dashboard.jpg\" alt=\"調剤・監査ダッシュボード画面。本日の受付状況と進行中の患者カードが一覧表示されている\" width=\"1600\" height=\"1000\" fetchpriority=\"high\">\n          </figure>\n          <figure class=\"showcase-panel\" id=\"panel-ocr\" role=\"tabpanel\" aria-labelledby=\"tab-ocr\" hidden>\n            <img src=\"/images/lp/ocr.jpg\" alt=\"処方箋受付画面。OCR読取・手入力受付・マイナ読取・処方箋QR取込が並ぶ\" width=\"1600\" height=\"1000\" fetchpriority=\"low\" loading=\"lazy\">\n          </figure>\n          <figure class=\"showcase-panel\" id=\"panel-picking\" role=\"tabpanel\" aria-labelledby=\"tab-picking\" hidden>\n            <img src=\"/images/lp/picking.jpg\" alt=\"ピッキング支援画面。棚番地A-01/B-03の薬品カードとバーコード読取欄、不足記録ボタン\" width=\"1600\" height=\"1000\" fetchpriority=\"low\" loading=\"lazy\">\n          </figure>\n          <figure class=\"showcase-panel\" id=\"panel-emr\" role=\"tabpanel\" aria-labelledby=\"tab-emr\" hidden>\n            <img src=\"/images/lp/emr-soap.jpg\" alt=\"薬歴入力画面。副作用歴アラート、構造化チェック、SOAP入力、前回薬歴、疑義照会、トレーシングレポート\" width=\"1600\" height=\"1000\" fetchpriority=\"low\" loading=\"lazy\">\n          </figure>\n          <figure class=\"showcase-panel\" id=\"panel-print\" role=\"tabpanel\" aria-labelledby=\"tab-print\" hidden>\n            <img src=\"/images/lp/print.jpg\" alt=\"帳票印刷・算定点検画面。合計点数、UKE点検ボタン、ステータスカード、外部調剤機器連携\" width=\"1600\" height=\"1000\" fetchpriority=\"low\" loading=\"lazy\">\n          </figure>\n          <figure class=\"showcase-panel\" id=\"panel-inventory\" role=\"tabpanel\" aria-labelledby=\"tab-inventory\" hidden>\n            <img src=\"/images/lp/inventory.jpg\" alt=\"在庫管理・発注画面。不足している薬の発注候補カードと納品書OCR・棚卸タブ\" width=\"1600\" height=\"1000\" fetchpriority=\"low\" loading=\"lazy\">\n          </figure>\n        </div>\n        <div class=\"showcase-caption\">\n          <span id=\"showcase-caption-text\"><strong>ダッシュボード：</strong>今日の受付件数、お待ちの患者さん、未完了の作業（ピッキング未照合・請求チェック・在庫不足）がひと目でわかります。</span>\n          <span>表示データはすべて架空のサンプルです</span>\n        </div>\n      </div>\n    </section>\n\n    <!-- ==================== 4 REASONS TO CHOOSE ==================== -->\n    <section id=\"pillars\" aria-labelledby=\"pillars-title\">\n      <div class=\"section-head\">\n        <p class=\"eyebrow\">Why pharma-oss</p>\n        <h2 id=\"pillars-title\">忙しい薬局の毎日を、ラクに・確実にする4つの特徴。</h2>\n        <p>「入力に時間がかかる」「取り違えや算定漏れが怖い」「毎月のシステム代が高い」——現場でよくある悩みに正面から応える設計です。</p>\n      </div>\n\n      <div class=\"pillars\" role=\"list\">\n        <article class=\"pillar\" role=\"listitem\">\n          <div class=\"pillar-head\">\n            <span class=\"pillar-num\">POINT 01 — スピードと時短</span>\n          </div>\n          <h3>処方入力も薬歴書きも、毎日の手作業をグッと短縮。</h3>\n          <p>\n            処方箋のQRコードやカメラOCRで受付入力を省力化。薬歴画面では「前回の処方との違い」が自動でハイライトされ、確認項目にチェックを入れるだけでSOAPの下書きが立ち上がるので、閉局後の薬歴残業を減らせます。\n          </p>\n          <div class=\"pillar-tags\">\n            <span class=\"pillar-tag\">処方箋QR・OCR読取</span>\n            <span class=\"pillar-tag\">前回Do・処方差分表示</span>\n            <span class=\"pillar-tag\">SOAP下書き自動作成</span>\n            <span class=\"pillar-tag\">キーボード操作対応</span>\n          </div>\n        </article>\n\n        <article class=\"pillar\" role=\"listitem\">\n          <div class=\"pillar-head\">\n            <span class=\"pillar-num\">POINT 02 — ヒヤリハット・返戻防止</span>\n          </div>\n          <h3>バーコード照合と多層チェックで、うっかりミスを未然にストップ。</h3>\n          <p>\n            ピッキング時にGS1バーコードを読むだけで「薬品・期限・ロット」の一致を確認。さらに患者さんのアレルギー歴・飲み合わせ（併用禁忌）・同効薬の重複から、レセプト出力前のコード抜け・廃止薬チェックまで自動で点検します。\n          </p>\n          <div class=\"pillar-tags\">\n            <span class=\"pillar-tag\">GS1バーコード現物照合</span>\n            <span class=\"pillar-tag\">アレルギー・相互作用警告</span>\n            <span class=\"pillar-tag\">照合未了のまま完了させない保護</span>\n            <span class=\"pillar-tag\">レセプト出力前チェック</span>\n          </div>\n        </article>\n\n        <article class=\"pillar\" role=\"listitem\">\n          <div class=\"pillar-head\">\n            <span class=\"pillar-num\">POINT 03 — 在庫と発注が直結</span>\n          </div>\n          <h3>「調剤中に薬が足りない」がその場で発注リストに。</h3>\n          <p>\n            ピッキング中に棚不足を記録すると、そのまま在庫画面の「発注ワークベンチ」に自動で集まります。発注点を下回った薬や期限が迫った薬も一覧でわかり、同じ効能の代替薬探しや納品書OCRでの入庫もスムーズです。\n          </p>\n          <div class=\"pillar-tags\">\n            <span class=\"pillar-tag\">棚不足→発注リスト直結</span>\n            <span class=\"pillar-tag\">代替薬のワンクリック検索</span>\n            <span class=\"pillar-tag\">納品書OCR・卸CSV入庫</span>\n            <span class=\"pillar-tag\">麻薬・向精神薬の棚卸</span>\n          </div>\n        </article>\n\n        <article class=\"pillar\" role=\"listitem\">\n          <div class=\"pillar-head\">\n            <span class=\"pillar-num\">POINT 04 — コストゼロ＆ネット不調でも止まらない</span>\n          </div>\n          <h3>月額費用0円。院内PCで動くから通信トラブルの日も安心。</h3>\n          <p>\n            高額な専用サーバーや月額ライセンス料は不要です。お店のパソコンの中で軽快に動作するため、光回線の不調時でも受付・薬歴・印刷が止まりません。受付や調剤室で複数台のタブレット・PCをつなぐ運用にも対応しています。\n          </p>\n          <div class=\"pillar-tags\">\n            <span class=\"pillar-tag\">月額利用料・更新料 0円</span>\n            <span class=\"pillar-tag\">オフラインでも業務継続</span>\n            <span class=\"pillar-tag\">複数PC・タブレット連携</span>\n            <span class=\"pillar-tag\">暗号化バックアップ</span>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <!-- ==================== END-TO-END WORKFLOW ==================== -->\n    <section id=\"workflow\" class=\"deferred-section\" aria-labelledby=\"flow-title\">\n      <div class=\"section-head\">\n        <p class=\"eyebrow\">Daily Workflow</p>\n        <h2 id=\"flow-title\">来局から会計・発注まで、薬局の1日の流れに沿って使えます。</h2>\n        <p>難しい操作を覚える必要はありません。いつもの業務の順番通りに画面を進めるだけで、抜け漏れなく処理が終わります。</p>\n      </div>\n\n      <!-- STEP 01 -->\n      <div class=\"flow-row\">\n        <div class=\"flow-copy\">\n          <p class=\"flow-step\">STEP 01 — 処方箋受付・患者呼び出し</p>\n          <h3>処方箋を読み取り、原本と並べてスムーズに受付。</h3>\n          <p>\n            処方箋のQRコード読み取り、カメラ・画像からの文字読み取り（OCR）、マイナ資格確認端末の連携フォルダ取込、手入力に対応。\n            処方箋の画像と入力欄を左右に並べて見比べられるので、画面を切り替えずに確認できます。\n          </p>\n          <ul class=\"flow-list\">\n            <li><strong>再来患者さんを自動で名寄せ</strong> — 氏名と生年月日から登録済みの患者さんを自動で探し出し、重複登録を防ぎます</li>\n            <li><strong>一般名処方【般】や公的用法マスタに標準対応</strong> — よく使う用法の検索や、第1〜第3公費までの複数公費の入力・保持に対応しています</li>\n          </ul>\n          <div class=\"chip-row\">\n            <span class=\"chip\">処方箋QR読取</span>\n            <span class=\"chip\">カメラ・画像OCR</span>\n            <span class=\"chip\">マイナ結果XML取込</span>\n            <span class=\"chip\">患者さんの自動名寄せ</span>\n          </div>\n        </div>\n        <figure class=\"flow-media\">\n          <img src=\"/images/lp/ocr.jpg\" alt=\"処方箋受付画面\" width=\"1600\" height=\"1000\" loading=\"lazy\">\n          <figcaption>処方箋受付画面 — QR・OCR・マイナ連携フォルダ・手入力から選んで受付</figcaption>\n        </figure>\n      </div>\n\n      <!-- STEP 02 -->\n      <div class=\"flow-row reverse\">\n        <div class=\"flow-copy\">\n          <p class=\"flow-step\">STEP 02 — ピッキング・取り違え防止</p>\n          <h3>棚番地通りに集めて、バーコードでピッと現物確認。</h3>\n          <p>\n            処方内容から「棚番地順」のピッキングリストを自動表示。薬の箱やシートのGS1バーコードを読み取るだけで、処方された薬と合っているか、使用期限が切れていないかをその場で判定します。\n          </p>\n          <ul class=\"flow-list\">\n            <li><strong>その場で「棚不足」を記録</strong> — 在庫が足りないときはワンクリックで不足記録を残せ、後から発注画面でまとめて確認できます</li>\n            <li><strong>既存の調剤機器・ピッキング機とも連携</strong> — ピッキング指示CSVの入出力や、NSIPS対応の分包機・調剤機器への処方送信に対応しています</li>\n          </ul>\n          <div class=\"chip-row\">\n            <span class=\"chip\">棚番地順リスト</span>\n            <span class=\"chip\">GS1バーコード照合</span>\n            <span class=\"chip\">使用期限・ロット確認</span>\n            <span class=\"chip\">調剤機器・CSV連携</span>\n          </div>\n        </div>\n        <figure class=\"flow-media\">\n          <img src=\"/images/lp/picking.jpg\" alt=\"ピッキング支援モード画面\" width=\"1600\" height=\"1000\" loading=\"lazy\">\n          <figcaption>ピッキング支援画面 — 棚番地ガイド・GS1バーコード照合・レジロール印刷</figcaption>\n        </figure>\n      </div>\n\n      <!-- STEP 03 -->\n      <div class=\"flow-row\">\n        <div class=\"flow-copy\">\n          <p class=\"flow-step\">STEP 03 — 服薬指導・電子薬歴（SOAP）</p>\n          <h3>前回との違いがすぐわかり、薬歴がサッと書ける。</h3>\n          <p>\n            「前回の薬歴」「今回変わった薬」「アレルギー・副作用歴」「飲み合わせの注意」が1つの画面にまとまっています。\n            服薬状況や残薬、副作用の有無をポチッと選ぶだけでSOAPの下書きが作られ、薬剤師が確認・手直ししてすぐに保存できます。\n          </p>\n          <ul class=\"flow-list\">\n            <li><strong>アレルギー・併用禁忌・重複投薬を自動チェック</strong> — 添付文書データをもとに、注意が必要な組み合わせや同効薬の重複をわかりやすく知らせます</li>\n            <li><strong>疑義照会・トレーシングレポートも1画面で</strong> — 疑義照会の記録や、処方医への服薬情報提供書の作成・印刷、来局後のフォローアップ予定までこの画面で完結します</li>\n          </ul>\n          <div class=\"chip-row\">\n            <span class=\"chip\">4パネルSOAP薬歴</span>\n            <span class=\"chip\">前回処方との差分表示</span>\n            <span class=\"chip\">飲み合わせ・アレルギー警告</span>\n            <span class=\"chip\">トレーシングレポート印刷</span>\n          </div>\n        </div>\n        <figure class=\"flow-media\">\n          <img src=\"/images/lp/emr-soap.jpg\" alt=\"薬歴入力画面\" width=\"1600\" height=\"1000\" loading=\"lazy\">\n          <figcaption>電子薬歴画面 — 構造化チェック・前回比較・安全アラート・トレーシングレポートを1画面に集約</figcaption>\n        </figure>\n      </div>\n\n      <!-- STEP 04 -->\n      <div class=\"flow-row reverse\">\n        <div class=\"flow-copy\">\n          <p class=\"flow-step\">STEP 04 — 会計・帳票印刷・レセプト（UKE）出力</p>\n          <h3>薬袋・手帳シールをすぐ印刷。レセプト前の点検も自動で。</h3>\n          <p>\n            令和8年（2026年）調剤報酬にもとづき、調剤基本料・薬剤調製料・各種加算や窓口負担金を自動計算。\n            領収証・明細書・薬袋・薬情・お薬手帳シールを必要な分だけ選んで、ブラウザから直接プリンターへ印刷できます。\n          </p>\n          <ul class=\"flow-list\">\n            <li><strong>返戻を防ぐ「請求前ダブルチェック」</strong> — レセプト（UKE）を作る前に、必須項目の抜けや経過措置切れの薬がないかを自動点検し、修正箇所を教えてくれます</li>\n            <li><strong>単票プレビュー＆月次一括UKE出力</strong> — 1件ごとのUKEレコード内容の確認から、月末の審査支払機関向けUKEファイル一括出力、返戻・再請求の管理まで対応しています</li>\n          </ul>\n          <div class=\"chip-row\">\n            <span class=\"chip\">令和8年調剤報酬算定</span>\n            <span class=\"chip\">11種帳票ダイレクト印刷</span>\n            <span class=\"chip\">UKE出力前エラー点検</span>\n            <span class=\"chip\">返戻・再請求管理</span>\n          </div>\n        </div>\n        <figure class=\"flow-media\">\n          <img src=\"/images/lp/print.jpg\" alt=\"帳票印刷・算定請求前点検画面\" width=\"1600\" height=\"1000\" loading=\"lazy\">\n          <figcaption>会計・帳票・レセプト確認画面 — 点数算定・各種帳票印刷・UKEプレビュー</figcaption>\n        </figure>\n      </div>\n\n      <!-- STEP 05 -->\n      <div class=\"flow-row\">\n        <div class=\"flow-copy\">\n          <p class=\"flow-step\">STEP 05 — 在庫管理・発注ワークベンチ・棚卸</p>\n          <h3>足りない薬・期限が近い薬を、自動でリストアップ。</h3>\n          <p>\n            「調剤で不足した薬」「発注点を切った薬」「使用期限が近い薬」が1つの画面に自動で集まります。\n            推奨発注数を参考にしながら発注CSVを出力でき、万が一の欠品時には同じ成分・同効の代替薬もすぐに探せます。\n          </p>\n          <ul class=\"flow-list\">\n            <li><strong>納品書OCR＆バーコード入庫</strong> — 卸の納品書をカメラや画像で読み取るか、箱のバーコードを読むだけで、ロット・使用期限つきの入庫登録が簡単に終わります</li>\n            <li><strong>麻薬・向精神薬の棚卸と不動在庫チェック</strong> — 帳簿残高と実在庫の突き合わせ記録や、動きのないデッドストックの抽出も標準で行えます</li>\n          </ul>\n          <div class=\"chip-row\">\n            <span class=\"chip\">発注ワークベンチ</span>\n            <span class=\"chip\">納品書OCR・CSV入庫</span>\n            <span class=\"chip\">同効・代替薬の検索</span>\n            <span class=\"chip\">麻薬・向精神薬棚卸</span>\n          </div>\n        </div>\n        <figure class=\"flow-media\">\n          <img src=\"/images/lp/inventory.jpg\" alt=\"在庫管理・発注ワークベンチ画面\" width=\"1600\" height=\"1000\" loading=\"lazy\">\n          <figcaption>在庫・発注管理画面 — 不足薬の発注候補リスト・納品書OCR・棚卸</figcaption>\n        </figure>\n      </div>\n\n      <!-- STEP 06 -->\n      <div class=\"flow-row reverse\">\n        <div class=\"flow-copy\">\n          <p class=\"flow-step\">STEP 06 — 受付・調剤室・投薬カウンターでの複数端末連携</p>\n          <h3>お店の複数PC・タブレットでも、安全に同時作業。</h3>\n          <p>\n            「受付で処方箋を入力しながら、調剤室でピッキングし、投薬カウンターで薬歴を書く」といった複数台での運用にも対応。\n            メインのPC1台にデータをまとめ、サブのタブレット等にはデータを残さない仕組みなので、端末の紛失や故障時も安心です。\n          </p>\n          <ul class=\"flow-list\">\n            <li><strong>設定画面からワンクリックで端末追加・解除</strong> — 難しいネットワーク構築なしで、店舗内LANでサブ端末を追加・管理できます</li>\n            <li><strong>同時編集時も上書き事故を防止</strong> — 同じ患者さんの記録を別々の端末で同時に触ってしまった場合も、勝手に消えず確認画面で安全に見比べて反映できます</li>\n          </ul>\n          <div class=\"chip-row\">\n            <span class=\"chip\">店舗内複数PC・タブレット対応</span>\n            <span class=\"chip\">サブ端末にデータを残さない安心設計</span>\n            <span class=\"chip\">同時編集の上書き防止</span>\n          </div>\n        </div>\n        <figure class=\"flow-media\">\n          <img src=\"/images/lp/terminal-sync.jpg\" alt=\"端末同期設定画面\" width=\"1600\" height=\"1000\" loading=\"lazy\">\n          <figcaption>複数端末連携画面 — サブ端末の登録・管理と、同時編集時の確認画面</figcaption>\n        </figure>\n      </div>\n    </section>\n\n    <!-- ==================== 11 PRINT SHEETS & OPERATIONS ==================== -->\n    <section id=\"operations\" class=\"deferred-section\" aria-labelledby=\"ops-title\">\n      <div class=\"section-head\">\n        <p class=\"eyebrow\">Print Suite &amp; Store Management</p>\n        <h2 id=\"ops-title\">11種類の帳票印刷から、日次締め・マスタ更新までこれ1つに。</h2>\n        <p>有料オプションや別ソフトの追加購入は不要です。毎日の窓口で使う印刷物も、月末・閉局時の管理機能もすべて最初から入っています。</p>\n      </div>\n\n      <div class=\"sheets-banner\" aria-label=\"出力対応帳票一覧\">\n        <h3>お使いのプリンターでそのまま出せる11種類の帳票（余白・文字サイズの微調整もOK）</h3>\n        <p>A4・A5・B5プリンターや薬袋、お薬手帳シール、レシート用サーマルプリンター（レジロール）まで、店舗の用紙に合わせて余白や文字サイズを画面上で調整できます。</p>\n        <div class=\"sheets-pills\" role=\"list\">\n          <span class=\"sheet-pill\" role=\"listitem\">調剤録 <small>裏面/表面</small></span>\n          <span class=\"sheet-pill\" role=\"listitem\">調剤明細書 <small>算定内訳つき</small></span>\n          <span class=\"sheet-pill\" role=\"listitem\">領収証 <small>負担割合・内訳</small></span>\n          <span class=\"sheet-pill\" role=\"listitem\">薬袋 <small>内服/外用/頓服</small></span>\n          <span class=\"sheet-pill\" role=\"listitem\">薬剤情報提供文書（薬情） <small>写真・注意事項</small></span>\n          <span class=\"sheet-pill\" role=\"listitem\">お薬手帳シール <small>長尺・複数頁対応</small></span>\n          <span class=\"sheet-pill\" role=\"listitem\">水剤ラベル <small>内用液剤用</small></span>\n          <span class=\"sheet-pill\" role=\"listitem\">軟膏ラベル <small>外用塗布剤用</small></span>\n          <span class=\"sheet-pill\" role=\"listitem\">ピッキングリスト <small>レジロール対応</small></span>\n          <span class=\"sheet-pill\" role=\"listitem\">服薬情報提供書 <small>トレーシングレポート</small></span>\n          <span class=\"sheet-pill\" role=\"listitem\">緊急復旧キー控えシート <small>金庫保管用</small></span>\n        </div>\n      </div>\n\n      <div class=\"grid\" role=\"list\">\n        <div class=\"cell\" role=\"listitem\">\n          <div class=\"cell-kicker\">閉局時の確認</div>\n          <h4>日次締め＆未完了チェック</h4>\n          <p>営業終了前に「薬歴の未入力」「未照合の処方」「在庫不足」「フォロー予定」をまとめて確認し、やり残しを防げます。</p>\n        </div>\n        <div class=\"cell\" role=\"listitem\">\n          <div class=\"cell-kicker\">万が一の備え</div>\n          <h4>かんたん暗号化バックアップ</h4>\n          <p>パスワード付きのバックアップファイルをワンクリックで保存。復元する前に「何が変わるか」を画面で確認できるので安心です。</p>\n        </div>\n        <div class=\"cell\" role=\"listitem\">\n          <div class=\"cell-kicker\">薬価改定・新薬対応</div>\n          <h4>医薬品マスタの取込更新</h4>\n          <p>支払基金が公開している最新の医薬品マスタ（CSV/ZIP）をそのまま取り込んで更新。間違えて戻せるロールバック機能つきです。</p>\n        </div>\n        <div class=\"cell\" role=\"listitem\">\n          <div class=\"cell-kicker\">近隣病院の登録</div>\n          <h4>医療機関マスタの都道府県取込</h4>\n          <p>地方厚生局の公開データから、お使いの都道府県の病院・クリニック・歯科マスタを一括で取り込めます。</p>\n        </div>\n        <div class=\"cell\" role=\"listitem\">\n          <div class=\"cell-kicker\">データの整理</div>\n          <h4>重複した患者・薬品の統合</h4>\n          <p>誤って2重に登録してしまった患者さんや医薬品を検出し、これまでの薬歴や在庫履歴をつないだまま1つにまとめられます。</p>\n        </div>\n        <div class=\"cell\" role=\"listitem\">\n          <div class=\"cell-kicker\">スタッフごとの権限</div>\n          <h4>薬剤師・事務の権限分け＆指紋認証</h4>\n          <p>管理者・薬剤師・医療事務ごとに操作できる範囲を設定可能。パスキー（指紋・顔認証）での素早いログインや離席時の自動ロックに対応。</p>\n        </div>\n        <div class=\"cell\" role=\"listitem\">\n          <div class=\"cell-kicker\">操作履歴の保護</div>\n          <h4>いつ・誰が操作したかを自動記録</h4>\n          <p>処方や薬歴の確定、算定の変更などの履歴を自動で記録。後から書き換えられない形で安全に保管できます。</p>\n        </div>\n        <div class=\"cell\" role=\"listitem\">\n          <div class=\"cell-kicker\">新人研修・お試しに</div>\n          <h4>いつでも消せる「3分練習モード」</h4>\n          <p>練習用のデモ患者さんをワンクリックで呼び出して一通りの操作を練習でき、終わったらボタン1つできれいに消去できます。</p>\n        </div>\n      </div>\n    </section>\n\n    <!-- ==================== STORE USAGE STYLES ==================== -->\n    <section id=\"architecture\" class=\"deferred-section\" aria-labelledby=\"arch-title\">\n      <div class=\"section-head\">\n        <p class=\"eyebrow\">How It Works in Your Pharmacy</p>\n        <h2 id=\"arch-title\">1台のPCからすぐ始められて、お店の規模に合わせて広げられます。</h2>\n        <p>大がかりなサーバー工事や専用回線は必要ありません。お店のスタイルに合わせて、シンプルな構成で利用できます。</p>\n      </div>\n\n      <div class=\"arch-layout\">\n        <div class=\"arch-card\">\n          <h3>選べる2つの運用スタイル</h3>\n          <div class=\"arch-diagram\">\n            <div class=\"arch-mode\">\n              <div class=\"arch-mode-title\">\n                <span>① PC 1台でシンプルに使う（小規模薬局・お試しに）</span>\n                <span class=\"arch-mode-badge\">すぐ使えます</span>\n              </div>\n              <div class=\"arch-nodes\">\n                <span class=\"arch-node\">お店のPC 1台</span>\n                <span class=\"arch-arrow\">→</span>\n                <span class=\"arch-node\">受付・薬歴・帳票印刷・UKE出力</span>\n                <span class=\"arch-arrow\">→</span>\n                <span class=\"arch-node\">外付けUSB等へバックアップ</span>\n              </div>\n            </div>\n            <div class=\"arch-mode\">\n              <div class=\"arch-mode-title\">\n                <span>② 受付・調剤室・投薬カウンターの複数台で使う</span>\n                <span class=\"arch-mode-badge\">店舗内LAN連携</span>\n              </div>\n              <div class=\"arch-nodes\">\n                <span class=\"arch-node\">メインPC（データを一括保管）</span>\n                <span class=\"arch-arrow\">⇄</span>\n                <span class=\"arch-node\">受付PC・調剤室タブレット（画面操作のみ）</span>\n              </div>\n            </div>\n            <div class=\"arch-mode\">\n              <div class=\"arch-mode-title\">\n                <span>③ 既存のピッキング機・分包機・資格確認端末とつなぐ</span>\n                <span class=\"arch-mode-badge\">機器・フォルダ連携</span>\n              </div>\n              <div class=\"arch-nodes\">\n                <span class=\"arch-node\">pharma-oss</span>\n                <span class=\"arch-arrow\">⇄</span>\n                <span class=\"arch-node\">資格確認端末の共有フォルダ / 分包機（NSIPS・CSV）</span>\n              </div>\n            </div>\n          </div>\n          <p style=\"margin:0;font-size:0.84rem;color:var(--lp-text-muted);\">\n            ※既存のレセコンを使いながら、「まずはピッキング照合や電子薬歴、在庫発注管理だけpharma-ossを使う」といった段階的な併用もスムーズに行えます。\n          </p>\n        </div>\n\n        <div class=\"arch-card\">\n          <h3>動作環境・仕様概要</h3>\n          <table class=\"spec-table\" aria-label=\"動作環境と仕様\">\n            <tbody>\n              <tr>\n                <th>対応端末</th>\n                <td>Windows / Mac の一般的なパソコン、タブレット（Chrome / Edge / Safari 等の最新ブラウザ）</td>\n              </tr>\n              <tr>\n                <th>利用料金・ライセンス</th>\n                <td>完全無料（Apache-2.0 オープンソースライセンス・商用利用可）</td>\n              </tr>\n              <tr>\n                <th>対応バーコード</th>\n                <td>GS1データバー（医療用医薬品）、JANコード、JAHIS処方箋2次元シンボル（QR） — 一般的なUSB/Bluetoothバーコードリーダーやカメラに対応</td>\n              </tr>\n              <tr>\n                <th>対応マスタ</th>\n                <td>支払基金 医薬品マスタ、厚生労働省 電子処方箋用法マスタ（1,803件）、地方厚生局 医療機関マスタ、PMDA添付文書相互作用データ</td>\n              </tr>\n              <tr>\n                <th>データ移行・出力</th>\n                <td>患者・薬歴CSV取込、審査支払機関向けUKE出力（Shift-JIS）、発注CSV出力、監査ログ・バックアップ出力</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </section>\n\n    <!-- ==================== HONEST STATUS & DISCLAIMER ==================== -->\n    <section id=\"status\" class=\"deferred-section\" aria-labelledby=\"status-title\">\n      <div class=\"section-head\">\n        <p class=\"eyebrow\">Capabilities &amp; Notice</p>\n        <h2 id=\"status-title\">現在できること・実機確認が必要なこと・未対応のこと。</h2>\n        <p>導入してから「思っていたのと違った」ということが起きないよう、現在使える機能と未対応の機能を正直に公開しています。</p>\n      </div>\n\n      <div class=\"status-grid\" role=\"list\">\n        <div class=\"status-col\" role=\"listitem\">\n          <span class=\"status-badge ok\">● すぐ使える機能</span>\n          <h3>パソコン1台ですぐ動くもの</h3>\n          <ul>\n            <li><strong>処方箋OCR・QR読取・手入力受付</strong>と患者さんの自動名寄せ</li>\n            <li><strong>GS1バーコードでのピッキング照合</strong>、棚不足の記録、ピッキングCSV入出力</li>\n            <li><strong>SOAP電子薬歴</strong>、前回比較、アレルギー・飲み合わせ・重複チェック、AI下書き補助、疑義照会・トレーシングレポート</li>\n            <li><strong>令和8年調剤報酬ベースの点数計算</strong>、請求前チェック、公式仕様ベースのUKEプレビュー・一括出力、返戻管理</li>\n            <li><strong>11種類の帳票印刷</strong>、<strong>在庫・発注管理</strong>、<strong>複数端末連携</strong>、<strong>バックアップ</strong></li>\n          </ul>\n        </div>\n\n        <div class=\"status-col\" role=\"listitem\">\n          <span class=\"status-badge warn\">▲ 機器とつなぐ前にテストが必要な機能</span>\n          <h3>店舗の機器との接続確認が必要なもの</h3>\n          <ul>\n            <li><strong>マイナ資格確認端末のフォルダ取込</strong> — 資格確認端末が出力する結果XMLから氏名・生年月日・保険者番号を取り込む機能を備えていますが、お使いの端末環境での事前テストをお願いします。</li>\n            <li><strong>分包機・調剤機器とのNSIPS連携</strong> — 連携用コネクタを通じた処方送信に対応していますが、接続する機器ごとの疎通確認が必要です。</li>\n            <li><strong>UKEファイルの提出確認</strong> — 審査支払機関の本番受付システムへ提出する際は、事前に受付点検ソフト等で必ず内容をご確認ください。</li>\n          </ul>\n        </div>\n\n        <div class=\"status-col\" role=\"listitem\">\n          <span class=\"status-badge unimpl\">■ 現在未対応の機能</span>\n          <h3>迷わないよう画面上で「未実装」と表示</h3>\n          <ul>\n            <li><strong>電子処方箋のオンライン取得（未対応）</strong> — 電子処方箋管理サービスへ直接つなぐ機能は未対応のため、紙の処方箋または処方箋QRをご利用ください。</li>\n            <li><strong>オンライン資格確認の直接照会（未対応）</strong> — リアルタイム照会は未対応のため、保険証・資格確認書の入力または連携フォルダ取込をご利用ください。</li>\n            <li><strong>マイナ特定健診・薬剤履歴の取込（未対応）</strong> — 仕様書未公開のため、画面上のボタンは押せないように明示しています。</li>\n          </ul>\n        </div>\n      </div>\n\n      <div class=\"honesty\" id=\"safety\">\n        <span class=\"label\">⚠️ ご利用にあたっての注意事項（免責事項）</span>\n        <h3>実運用時は、薬剤師による最終確認と最新の公式基準との照合をお願いします。</h3>\n        <p>\n          pharma-oss は無償で公開されているオープンソースソフトウェア（Apache License 2.0）であり、薬機法上の認証医療機器や公式認定レセプトコンピュータではありません。\n          実際の調剤業務や保険請求にご利用になる場合は、点数算定・医薬品マスタ・帳票・出力UKEファイルの内容が最新の厚生労働省告示や支払基金の仕様と合っているか、<strong>ご利用になる薬局・薬剤師ご自身の責任で最終確認</strong>をお願いいたします。\n        </p>\n        <ul>\n          <li>同梱されている医薬品マスタや飲み合わせデータは公開情報をもとにしたスナップショットです。実運用を始める前に、「設定 &gt; マスタ更新」から最新の公式マスタを取り込んでご利用ください（データの出所は <a href=\"https://github.com/pharma-oss/pharma-oss/blob/main/NOTICE\">NOTICE</a> をご覧ください）。</li>\n          <li>画面上のAI下書きやアラート表示は業務を補助するための参考提示です。服薬指導・調剤・保険請求の最終判断は必ず薬剤師が行ってください。</li>\n        </ul>\n      </div>\n    </section>\n\n    <!-- ==================== GETTING STARTED & FAQ ==================== -->\n    <section id=\"start\" class=\"deferred-section\" aria-labelledby=\"start-title\">\n      <div class=\"section-head\">\n        <p class=\"eyebrow\">Getting Started</p>\n        <h2 id=\"start-title\">まずは3分、架空のデモ患者さんで触ってみませんか？</h2>\n        <p>面倒なアカウント登録や初期設定は不要です。最初から入っている練習用の患者データで、受付から薬歴・印刷まで一通り試せます。</p>\n      </div>\n\n      <div class=\"start-grid\">\n        <div class=\"terminal-card\">\n          <div class=\"terminal-head\">\n            <span>パソコンで動かす場合（4行で起動）</span>\n            <button type=\"button\" class=\"copy-btn\" id=\"copy-cmd-btn\" aria-label=\"コマンドをコピー\">コピー</button>\n          </div>\n          <pre aria-label=\"セットアップコマンド\"><code id=\"quickstart-code\"><span class=\"cmd\">git clone</span> https://github.com/pharma-oss/pharma-oss.git\n<span class=\"cmd\">cd</span> pharma-oss\n<span class=\"cmd\">npm install</span>\n<span class=\"cmd\">npm run dev</span>\n<span class=\"c\"># → ブラウザで http://localhost:3000 を開く</span></code></pre>\n        </div>\n\n        <div class=\"start-routes\">\n          <div class=\"route-card\">\n            <h3><span class=\"route-badge\">いちばん簡単</span> パスワード設定なしで今すぐ体験</h3>\n            <ol class=\"steps\">\n              <li>アプリを開き、最初の画面にある「<strong>デモ患者で体験を始める</strong>」（または画面右上の「<strong>3分デモ</strong>」）をクリックします。</li>\n              <li>ログイン不要のまま、架空の患者さん「<strong>デモ患者 みどり（68歳・ロキソプロフェン副作用歴あり・3剤処方）</strong>」の薬歴画面が開きます。</li>\n              <li><strong>ピッキング照合</strong> → <strong>SOAP薬歴の入力</strong> → <strong>薬袋・薬情・明細書の印刷プレビュー</strong>まで、実際の動きをそのまま体験できます。</li>\n            </ol>\n          </div>\n\n          <div class=\"route-card\">\n            <h3><span class=\"route-badge\">練習の後片付け</span> デモデータはワンクリックで消去</h3>\n            <ol class=\"steps\">\n              <li>練習用のデモ患者データは、毎月のレセプト（UKE）請求や分包機連携には混ざらないよう自動で区別されています。</li>\n              <li>操作を一通り試したあとは、ダッシュボード上部の「<strong>デモデータを片づける</strong>」ボタンを押すだけで、いつでもきれいに消去できます。</li>\n            </ol>\n          </div>\n        </div>\n      </div>\n\n      <!-- Searchable Native Details Accordion -->\n      <div class=\"faq-list\" aria-label=\"よくある質問\">\n        <details class=\"faq-item\" name=\"faq-group\" open>\n          <summary>Q. インターネット回線が切れても、本当に窓口業務を続けられますか？</summary>\n          <div class=\"faq-body\">\n            はい。患者さんのデータや薬品マスタはお使いのパソコン内に保存されているため、万が一ネットが繋がらなくなっても、処方箋の読み取り、ピッキング照合、薬歴の入力、薬袋や領収証の印刷、レセプトの作成までそのまま続けられます。\n          </div>\n        </details>\n        <details class=\"faq-item\" name=\"faq-group\">\n          <summary>Q. 受付のパソコンと、調剤室のタブレットで同時に使えますか？</summary>\n          <div class=\"faq-body\">\n            はい。メインのパソコン1台にデータをまとめ、受付や調剤室のパソコン・タブレットから社内LAN経由でつないで同時に作業できます。サブの端末側には患者データを残さない仕組みになっているため、タブレットの管理も安心です。詳しい手順は <a href=\"https://github.com/pharma-oss/pharma-oss/blob/main/docs/field_operation_manual.md\">現場運用マニュアル</a> でご案内しています。\n          </div>\n        </details>\n        <details class=\"faq-item\" name=\"faq-group\">\n          <summary>Q. 薬価改定や新薬が出たときのマスタ更新は難しくありませんか？</summary>\n          <div class=\"faq-body\">\n            アプリ内の「設定 &gt; マスタ更新」画面から、支払基金のホームページで公開されている医薬品マスタファイル（CSVまたはZIP）を選ぶだけで更新できます。更新前後の変更点リストも自動で作られ、万が一間違えたファイルを取り込んでもワンクリックで元の状態に戻せます。\n          </div>\n        </details>\n        <details class=\"faq-item\" name=\"faq-group\">\n          <summary>Q. 今使っているレセコンやピッキング機器と併用できますか？</summary>\n          <div class=\"faq-body\">\n            はい。既存の患者・薬歴データのCSV取り込みに対応しているほか、ピッキングリストのCSV出力・結果取込や、NSIPS形式での調剤機器連携を備えています。「まずはバーコードでのピッキング照合や電子薬歴、発注管理から使い始める」といった段階的な導入も可能です。\n          </div>\n        </details>\n      </div>\n    </section>\n  </main>\n</div>\n\n<!-- ==================== CTA BAND ==================== -->\n<div class=\"cta-band\">\n  <div class=\"wrap\">\n    <h2>毎日の薬局業務を、もっとシンプルで使いやすく。</h2>\n    <p>\n      pharma-oss は、どなたでも無料で試せるオープンソースの調剤薬局システムです。\n      まずはデモ患者データで、受付から薬歴・印刷までの使い心地を体験してみてください。\n    </p>\n    <div class=\"hero-ctas\">\n      <a class=\"btn btn-primary\" href=\"/app\">今すぐアプリを開く</a>\n      <a class=\"btn btn-ghost\" href=\"https://github.com/pharma-oss/pharma-oss/blob/main/docs/field_operation_manual.md\">現場運用マニュアル</a>\n      <a class=\"btn btn-ghost\" href=\"https://github.com/pharma-oss/pharma-oss/blob/main/docs/user_manual.md\">取扱説明書（全機能ガイド）</a>\n      <a class=\"btn btn-ghost\" href=\"https://github.com/pharma-oss/pharma-oss\">GitHubリポジトリ</a>\n    </div>\n  </div>\n</div>\n\n<!-- ==================== FOOTER ==================== -->\n<div class=\"wrap\">\n  <footer>\n    <div class=\"foot-row\">\n      <span>© 2026 pharma-oss Project Contributors — Licensed under <a href=\"https://github.com/pharma-oss/pharma-oss/blob/main/LICENSE\">Apache-2.0</a></span>\n      <div class=\"foot-links\">\n        <a href=\"https://github.com/pharma-oss/pharma-oss/blob/main/docs/user_manual.md\">取扱説明書</a>\n        <a href=\"https://github.com/pharma-oss/pharma-oss/blob/main/docs/field_operation_manual.md\">現場運用マニュアル</a>\n        <a href=\"https://github.com/pharma-oss/pharma-oss/blob/main/NOTICE\">同梱データの出所 (NOTICE)</a>\n        <a href=\"https://github.com/pharma-oss/pharma-oss/blob/main/SECURITY.md\">セキュリティ報告</a>\n        <a href=\"https://github.com/pharma-oss/pharma-oss\">GitHub</a>\n      </div>\n    </div>\n  </footer>\n</div>\n\n" }} />
    </div>
  );
}
